    content: `
      <p class="lead text-lg text-slate-700 leading-relaxed mb-6 font-medium">
        The 2 PM slump is rarely about willpower — it is usually about a <strong>high-protein lunch</strong> that never happened. Protein keeps blood sugar steady, protects lean muscle, and switches off hunger hormones for hours. Combine it with colorful vegetables and healthy fat, and you have the perfect anti-inflammatory lunch. Here are 12 ideas, each with 30+ grams of protein.
      </p>

      <h2 id="why-protein" class="text-2xl font-bold text-slate-900 mt-8 mb-4 border-b border-sage-light pb-2">
        1. Why High-Protein Lunches Keep You Balanced
      </h2>
      <ul class="list-disc pl-6 space-y-2 text-slate-700 mb-6">
        <li>Triggers fullness hormones (GLP-1 and PYY) that cut cravings by evening.</li>
        <li>Slows digestion of carbohydrates, smoothing glucose curves.</li>
        <li>Supports muscle preservation while your body focuses on repair.</li>
        <li>Pairs naturally with anti-inflammatory fats like olive oil and avocado.</li>
      </ul>
      <p class="mb-6 text-slate-700 leading-relaxed">
        Aim for <strong>30–40 grams</strong> at lunch. That is roughly one palm-sized portion of fish, poultry, or lean red meat, plus an egg or a scoop of seeds. These <strong>high protein recipes</strong> make it effortless.
      </p>

      <h2 id="the-formula" class="text-2xl font-bold text-slate-900 mt-8 mb-4 border-b border-sage-light pb-2">
        2. The 3-3-1 Lunch Formula
      </h2>
      <p class="mb-4 text-slate-700 leading-relaxed">
        You do not need to memorize recipes — just remember this pattern for every lunch:
      </p>
      <div class="bg-stone-50 border border-stone-200 rounded-xl p-4 mb-6 text-slate-700 text-sm leading-relaxed">
        <strong>3</strong> = 3 colors of vegetables (greens + orange + one more)<br />
        <strong>3</strong> = 3 sources of protein (fish + eggs + seeds, for example)<br />
        <strong>1</strong> = 1 healthy fat (olive oil, avocado, or olives)
      </div>

      <h2 id="bowls" class="text-2xl font-bold text-slate-900 mt-8 mb-4 border-b border-sage-light pb-2">
        3. High-Protein Bowl Ideas
      </h2>
      <ul class="list-disc pl-6 space-y-2 text-slate-700 mb-6">
        <li><strong>Golden Turmeric Salmon Bowl</strong> — wild salmon, roasted sweet potato, massaged kale, pumpkin seeds (~38g). Our signature bowl from the meal prep guide.</li>
        <li><strong>Greek-ish chicken bowl</strong> — grilled chicken, cucumber, olives, red onion, lemon-oregano dressing (~40g).</li>
        <li><strong>Sirloin strip sauté</strong> — lean beef strips, bell peppers, cauliflower rice, olive oil (~40g).</li>
        <li><strong>Egg &amp; avocado bowl</strong> — 3 eggs, avocado, sautéed spinach, hemp hearts (~28g).</li>
        <li><strong>Shrimp zoodle bowl</strong> — garlic shrimp over zucchini noodles, cherry tomatoes, basil (~32g).</li>
      </ul>

      <h2 id="salads-wraps" class="text-2xl font-bold text-slate-900 mt-8 mb-4 border-b border-sage-light pb-2">
        4. Salads, Wraps &amp; Handheld Lunches
      </h2>
      <ul class="list-disc pl-6 space-y-2 text-slate-700 mb-6">
        <li><strong>Turkey lettuce wraps</strong> — lean turkey mince, ginger-tamari, shredded carrots, on crisp lettuce (~31g).</li>
        <li><strong>Salmon salad plate</strong> — canned wild salmon, romaine, radishes, ACV vinaigrette (~34g).</li>
        <li><strong>Chicken-stuffed peppers</strong> — roasted bell peppers filled with chicken, cauliflower rice, herbs (~36g).</li>
        <li><strong>Egg muffin cups</strong> — baked egg, spinach and mushroom cups, plus a side of smoked trout (~28g).</li>
        <li><strong>Chickpea &amp; tuna bowl</strong> — a can of tuna, chickpeas, lemon, parsley (~38g).</li>
      </ul>

      <h2 id="stews" class="text-2xl font-bold text-slate-900 mt-8 mb-4 border-b border-sage-light pb-2">
        5. One-Pot Stews &amp; Batch Mains
      </h2>
      <p class="mb-4 text-slate-700 leading-relaxed">
        Batch mains are the backbone of anti-inflammatory meal prep. Cook once on Sunday, eat three days:
      </p>
      <ul class="list-disc pl-6 space-y-2 text-slate-700 mb-6">
        <li><strong>Grass-fed beef stew</strong> with shiitake, kale, and bone broth (~44g per bowl).</li>
        <li><strong>Lemon ginger chicken stew</strong> with sweet potato (~36g).</li>
        <li><strong>White bean &amp; turkey chili</strong> with tomatoes, cumin, and coriander (~34g).</li>
        <li><strong>Garlic halibut tray bake</strong> with asparagus and lemon ghee (~33g).</li>
      </ul>

      <h2 id="prep-tips" class="text-2xl font-bold text-slate-900 mt-8 mb-4 border-b border-sage-light pb-2">
        6. Sunday Prep Tips for 5 Lunches
      </h2>
      <ul class="list-disc pl-6 space-y-2 text-slate-700 mb-6">
        <li>Cook one large protein main (stew, roasted chicken, or baked fish) to cover 3–4 lunches.</li>
        <li>Roast a tray of vegetables (zucchini, pepper, sweet potato) in the same oven.</li>
        <li>Make one big dressing in a jar — olive oil, lemon, Dijon, herbs.</li>
        <li>Portion into glass containers immediately; label with the day.</li>
        <li>Keep greens and dressings separate so salads stay crisp until Thursday.</li>
      </ul>
      <p class="mb-6 text-slate-700 leading-relaxed">
        This exact system, with the grocery list and portions, is in the free <a href="/gut-glow-7-day-anti-inflammatory-meal-prep.pdf" download class="text-sage font-bold underline hover:text-sage-dark">7-Day Anti-Inflammatory Meal Prep &amp; Grocery Checklist PDF</a>.
      </p>

      <h2 id="lunch-faq" class="text-2xl font-bold text-slate-900 mt-8 mb-4 border-b border-sage-light pb-2">
        7. Frequently Asked Questions
      </h2>
      <div class="space-y-4 mb-4">
        <div>
          <h3 class="font-bold text-slate-900">How much protein do I really need at lunch?</h3>
          <p class="text-slate-700 leading-relaxed text-sm">For most women, 30–40 grams at lunch supports fullness and steady energy. Spread the rest across breakfast, dinner, and snacks.</p>
        </div>
        <div>
          <h3 class="font-bold text-slate-900">Are these high-protein lunch ideas vegetarian?</h3>
          <p class="text-slate-700 leading-relaxed text-sm">Most are pescatarian-friendly, and the egg and chickpea options work for vegetarians. Swap fish for tofu or tempeh in any bowl.</p>
        </div>
        <div>
          <h3 class="font-bold text-slate-900">Do high-protein lunches help with cravings?</h3>
          <p class="text-slate-700 leading-relaxed text-sm">Consistently, people who eat enough protein earlier in the day report fewer afternoon and evening cravings — because fullness hormones stay elevated longer.</p>
        </div>
        <div>
          <h3 class="font-bold text-slate-900">Can I prep these for the whole week?</h3>
          <p class="text-slate-700 leading-relaxed text-sm">Yes. Stews and roasted mains last 4–5 days in airtight glass containers. Assemble salads the morning of for maximum crispness.</p>
        </div>
      </div>

      <div class="my-10 p-6 bg-sage-light border-l-4 border-sage rounded-r-lg">
        <h4 class="font-bold text-sage-dark text-lg mb-2">Never Face Lunchtime Again</h4>
        <p class="text-slate-800 text-sm leading-relaxed">
          Pick two bowls and one stew from this list, prep them Sunday, and watch your 3 PM cravings disappear. Prefer a full plan? Grab the free 7-day meal prep PDF and start Monday with everything ready.
        </p>
      </div>
    `
